import hashlib
import math


class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array to track item membership.
    It uses multiple hash functions to reduce the probability of false positives based
    on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._get_optimal_size()
        self.hash_count = self._get_optimal_hash_count()
        self.bit_array = [0] * self.size

    def _get_optimal_size(self) -> int:
        """Calculate the optimal bit array size."""
        return math.ceil((-self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _get_optimal_hash_count(self) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash for the item based on a seed."""
        hash_obj = hashlib.md5((str(seed) + item).encode())
        return int(hash_obj.hexdigest(), 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for seed in range(self.hash_count):
            index = self._hash(item, seed)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        for seed in range(self.hash_count):
            index = self._hash(item, seed)
            if self.bit_array[index] == 0:
                return False
        return True

