class BloomFilter:
    """
    A Bloom Filter implementation to test membership of an item in a set with a specified false positive rate.
    The design uses a bit array and multiple hash functions to minimize the risk of false positives.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        # Calculate optimal bit array size and number of hash functions
        self.size = self.calculate_size(expected_items, false_positive_rate)
        self.num_hashes = self.calculate_num_hashes(self.size, expected_items)
        self.bit_array = [0] * self.size

    def calculate_size(self, n: int, p: float) -> int:
        """Calculate the size of the bit array needed."""
        return int(-n * math.log(p) / (math.log(2) ** 2))

    def calculate_num_hashes(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def hash(self, item: str, seed: int) -> int:
        """Create a hash of the item using a given seed."""
        hash_object = hashlib.md5((item + str(seed)).encode())
        return int(hash_object.hexdigest(), 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.num_hashes):
            index = self.hash(item, i)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        for i in range(self.num_hashes):
            index = self.hash(item, i)
            if self.bit_array[index] == 0:
                return False
        return True

